-- 데이터베이스 세트 373. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_git_history_tools_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 373, 'Git 이력 다듬기와 버그 찾기: rebase, merge --squash, bisect, clean, alias, restore --source, log -S', '작은 저장소에서 이력을 다듬고 문제를 찾는 도구를 직접 써 봅니다. bisect run 으로 버그가 처음 들어온 커밋을 찾고, 브랜치를 rebase 로 한 줄로 옮기고, 충돌 난 rebase 와 병합을 풀거나 취소하고, merge --squash 로 커밋 여럿을 하나로 합쳐 병합하고, git clean 으로 추적하지 않는 파일을 미리 보고 지우고, 별칭을 만들고, restore --source 로 옛 버전 파일을 되살리고, log -S 로 문자열이 나타나거나 사라진 커밋을 찾습니다. 채점은 저장소의 실제 상태를 git 명령으로 조회해 비교합니다.', 'linux', 'Git'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 373);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 1, '버그가 들어온 커밋 찾기 (git bisect run)', '**배경** — 커밋이 많을 때 "어느 커밋부터 망가졌지?" 를 일일이 확인하는 대신, `git bisect` 는 **이진 탐색** 으로 나쁜 커밋을 빠르게 찾아 줍니다. 좋은 커밋과 나쁜 커밋을 알려 주면 중간 커밋을 차례로 체크아웃해 가며 범위를 반씩 줄이고, `git bisect run 스크립트` 는 그 판정을 스크립트의 종료 코드(0 이면 좋음, 아니면 나쁨)로 자동화합니다. 이 세트의 문제는 `/tmp/lab/proj` 저장소를 씁니다(`main` 브랜치). 문제마다 처음 상태에서 다시 시작합니다.

**문제** — `main` 에는 커밋 8개가 있고, 첫 커밋은 좋고 최신 커밋은 나쁩니다. `/tmp/lab/check.sh`(저장소 안에서 실행하면 `cfg.txt` 가 `limit=10` 일 때만 성공하는 검사 스크립트)로 **버그가 처음 들어온 커밋** 을 찾아 그 **커밋 제목** 을 **`/tmp/q1.txt`** 에 저장하세요. 끝나면 `git bisect reset` 으로 원래 상태로 돌아와 있어야 합니다.', '`git bisect start 나쁜커밋 좋은커밋` 으로 시작하고 `git bisect run sh /tmp/lab/check.sh` 로 자동 판정합니다. 끝나면 `refs/bisect/bad` 가 처음 나쁜 커밋을 가리키니 `git log -1 --format=%s refs/bisect/bad` 로 제목을 읽고, 마지막에 `git bisect reset` 을 잊지 마세요.', 'cd /tmp/lab/proj
git bisect start HEAD $(git rev-list --max-parents=0 HEAD)
git bisect run sh /tmp/lab/check.sh
git log -1 --format=%s refs/bisect/bad > /tmp/q1.txt
git bisect reset
cat /tmp/q1.txt

# bisect run 이 이진 탐색으로 처음 나쁜 커밋을 찾는다. 끝나면 bisect reset 으로 원래 브랜치로 돌아온다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev; git config user.email dev@example.com; git config core.editor true\\nc() { GIT_AUTHOR_DATE=\\"2026-01-0$2T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$2T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\nfor i in 1 2 3 4; do echo ''limit=10'' > cfg.txt; echo \\"step $i\\" > notes.txt; git add -A; c \\"step $i\\" $i; done\\necho ''limit=50'' > cfg.txt; echo ''step 5'' > notes.txt; git add -A; c ''raise limit to 50'' 5\\nfor i in 6 7 8; do echo \\"step $i\\" > notes.txt; git add -A; c \\"step $i\\" $i; done\\nprintf ''#!/bin/sh\\\\n[ \\"$(cat cfg.txt)\\" = \\"limit=10\\" ]\\\\n'' > /tmp/lab/check.sh"]', '["sh", "-c", "( [ \\"$(cat /tmp/q1.txt)\\" = \\"raise limit to 50\\" ] ) && ( [ ! -e /tmp/lab/proj/.git/BISECT_LOG ] && [ \\"$(git -C /tmp/lab/proj rev-parse --abbrev-ref HEAD)\\" = main ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q1.txt 가 버그가 처음 들어온 커밋의 제목(raise limit to 50)이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q1.txt)\\" = \\"raise limit to 50\\" ]"]}, {"label": "bisect 가 끝나 있고 main 으로 돌아와 있다", "cmd": ["sh", "-c", "[ ! -e /tmp/lab/proj/.git/BISECT_LOG ] && [ \\"$(git -C /tmp/lab/proj rev-parse --abbrev-ref HEAD)\\" = main ]"]}]', '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 373 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 2, '내 브랜치를 최신 main 위로 옮기기 (git rebase)', '**배경** — `git rebase 기준` 은 지금 브랜치의 커밋들을 **기준 브랜치의 끝 위로 옮겨 다시 쌓습니다.** 병합(`merge`)과 달리 병합 커밋이 생기지 않아 이력이 **한 줄** 로 이어집니다. 대신 옮겨진 커밋은 내용은 같아도 **새 커밋(새 해시)** 이 됩니다.

**문제** — 브랜치 `feature`(커밋 2개)가 갈라진 뒤 `main` 에 새 커밋이 생겼습니다. 지금 `feature` 에 있습니다. `feature` 를 **최신 `main` 위로 rebase** 해서 이력이 한 줄이 되게 하세요. 병합 커밋은 만들지 마세요.', '`feature` 브랜치에 있는 채로 `git rebase main` 입니다. 끝나면 `git log --oneline --graph` 로 한 줄인지 확인할 수 있습니다.', 'cd /tmp/lab/proj
git rebase main
git log --oneline --graph

# feature 위에서 git rebase main. feature 의 커밋 2개가 main 의 끝 위로 새로 쌓인다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev; git config user.email dev@example.com; git config core.editor true\\nc() { GIT_AUTHOR_DATE=\\"2026-01-0$2T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$2T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho base > base.txt; git add -A; c base 1\\ngit switch -q -c feature\\necho f1 > f1.txt; git add -A; c ''feature 1'' 2\\necho f2 > f2.txt; git add -A; c ''feature 2'' 3\\ngit switch -q main\\necho m > main.txt; git add -A; c ''main change'' 4\\ngit switch -q feature"]', '["sh", "-c", "( [ \\"$(git -C /tmp/lab/proj merge-base main feature)\\" = \\"$(git -C /tmp/lab/proj rev-parse main)\\" ] ) && ( [ \\"$(git -C /tmp/lab/proj rev-list --count main..feature)\\" = 2 ] ) && ( [ \\"$(git -C /tmp/lab/proj rev-list --merges --count feature)\\" = 0 ] ) && ( [ \\"$(git -C /tmp/lab/proj log -1 --format=%s main)\\" = \\"main change\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "feature 가 main 의 끝에서 갈라진 상태(한 줄)다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj merge-base main feature)\\" = \\"$(git -C /tmp/lab/proj rev-parse main)\\" ]"]}, {"label": "feature 가 main 보다 정확히 2커밋 앞선다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj rev-list --count main..feature)\\" = 2 ]"]}, {"label": "병합 커밋이 없다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj rev-list --merges --count feature)\\" = 0 ]"]}, {"label": "main 은 그대로다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj log -1 --format=%s main)\\" = \\"main change\\" ]"]}]', '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 373 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 3, '브랜치의 커밋 여럿을 하나로 합쳐 병합하기 (merge --squash)', '**배경** — `git merge --squash 브랜치` 는 그 브랜치의 변경을 **한꺼번에 가져와 스테이징만** 합니다(커밋은 직접 해야 함). 그래서 브랜치의 커밋 여러 개가 `main` 에는 **커밋 하나** 로 남고, 병합 커밋도 생기지 않습니다.

**문제** — 브랜치 `topic` 에는 커밋 3개(`a.txt`, `b.txt`, `c.txt` 추가)가 있습니다. 지금 `main` 에 있습니다. `topic` 을 **squash 병합** 해서 `main` 에 **커밋 하나**(메시지 **`add topic`**)로 반영하세요.', '`git merge --squash topic` 다음에 `git commit -m 메시지` 를 직접 실행해야 커밋이 만들어집니다.', 'cd /tmp/lab/proj
git merge --squash topic
git commit -m ''add topic''
git log --oneline

# merge --squash 는 변경만 스테이징한다. 직접 commit 해야 main 에 커밋 하나로 남는다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev; git config user.email dev@example.com; git config core.editor true\\nc() { GIT_AUTHOR_DATE=\\"2026-01-0$2T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$2T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho base > base.txt; git add -A; c base 1\\ngit switch -q -c topic\\necho a > a.txt; git add -A; c ''topic a'' 2\\necho b > b.txt; git add -A; c ''topic b'' 3\\necho c > c.txt; git add -A; c ''topic c'' 4\\ngit switch -q main"]', '["sh", "-c", "( [ \\"$(git -C /tmp/lab/proj log -1 --format=%s main)\\" = \\"add topic\\" ] ) && ( [ \\"$(git -C /tmp/lab/proj rev-list --count main)\\" = 2 ] ) && ( [ \\"$(git -C /tmp/lab/proj ls-tree -r --name-only main | tr \\"\\\\n\\" \\" \\")\\" = \\"a.txt b.txt base.txt c.txt \\" ] ) && ( [ \\"$(git -C /tmp/lab/proj rev-list --merges --count main)\\" = 0 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "main 의 최신 커밋 제목이 add topic 이다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj log -1 --format=%s main)\\" = \\"add topic\\" ]"]}, {"label": "main 의 커밋은 base 와 add topic 두 개뿐이다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj rev-list --count main)\\" = 2 ]"]}, {"label": "a.txt, b.txt, c.txt 가 main 에 들어왔다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj ls-tree -r --name-only main | tr \\"\\\\n\\" \\" \\")\\" = \\"a.txt b.txt base.txt c.txt \\" ]"]}, {"label": "병합 커밋이 없다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj rev-list --merges --count main)\\" = 0 ]"]}]', '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 373 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 4, '추적 안 하는 파일 정리하기 (git clean)', '**배경** — `git clean` 은 Git 이 **추적하지 않는(untracked)** 파일을 지웁니다. 지우면 되돌릴 수 없어서, 먼저 `-n`(dry run)으로 **무엇이 지워질지 미리** 보고, 그 다음 `-f` 로 실제로 지우는 것이 안전합니다.

**문제** — 저장소에는 추적 중인 `notes.txt`(고친 상태)와 추적하지 않는 `a.tmp`, `b.tmp` 가 있습니다. 먼저 **지워질 목록 미리보기** 출력을 **`/tmp/q4.txt`** 에 저장한 뒤, 추적하지 않는 파일을 **실제로 지우세요.** 고친 `notes.txt` 는 그대로 남아야 합니다.', '`git clean -n` 이 미리보기, `git clean -f` 가 실제 삭제입니다. `git clean` 은 추적 중인 파일의 변경은 건드리지 않습니다.', 'cd /tmp/lab/proj
git clean -n > /tmp/q4.txt
git clean -f
cat /tmp/q4.txt
git status --short

# clean -n 으로 미리 보고 clean -f 로 지운다. 추적 중인 notes.txt 의 변경은 그대로다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev; git config user.email dev@example.com; git config core.editor true\\nc() { GIT_AUTHOR_DATE=\\"2026-01-0$2T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$2T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''v1'' > notes.txt; git add -A; c ''add notes'' 1\\necho ''changed'' > notes.txt; touch a.tmp b.tmp"]', '["sh", "-c", "( [ \\"$(sort /tmp/q4.txt)\\" = \\"$(printf \\"Would remove a.tmp\\\\nWould remove b.tmp\\")\\" ] ) && ( [ ! -e /tmp/lab/proj/a.tmp ] && [ ! -e /tmp/lab/proj/b.tmp ] ) && ( [ \\"$(git -C /tmp/lab/proj status --short)\\" = \\" M notes.txt\\" ] && [ \\"$(cat /tmp/lab/proj/notes.txt)\\" = changed ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q4.txt 에 지워질 목록(a.tmp, b.tmp)이 있다", "cmd": ["sh", "-c", "[ \\"$(sort /tmp/q4.txt)\\" = \\"$(printf \\"Would remove a.tmp\\\\nWould remove b.tmp\\")\\" ]"]}, {"label": "a.tmp, b.tmp 가 실제로 지워졌다", "cmd": ["sh", "-c", "[ ! -e /tmp/lab/proj/a.tmp ] && [ ! -e /tmp/lab/proj/b.tmp ]"]}, {"label": "고친 notes.txt 는 그대로 남아 있다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj status --short)\\" = \\" M notes.txt\\" ] && [ \\"$(cat /tmp/lab/proj/notes.txt)\\" = changed ]"]}]', '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 373 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 5, '긴 명령에 짧은 이름 붙이기 (git alias)', '**배경** — 자주 쓰는 긴 명령은 `git config alias.이름 "명령"` 으로 **짧은 이름(별칭)** 을 붙일 수 있습니다. 별칭 `st` 를 만들면 `git st` 가 그 명령으로 실행됩니다. `--local`(기본)이면 이 저장소에서만 적용됩니다.

**문제** — `/tmp/lab/proj` 저장소에서 **`git status -s`** 를 뜻하는 별칭 **`st`** 를 만들고, **`git st`** 를 실행한 출력을 **`/tmp/q5.txt`** 에 저장하세요.', '`git config alias.st "status -s"` 로 만들고, 저장소 안에서 `git st > 파일` 로 실행하세요. 별칭 값에는 앞에 `git` 을 쓰지 않습니다.', 'cd /tmp/lab/proj
git config alias.st ''status -s''
git st > /tmp/q5.txt
cat /tmp/q5.txt

# alias.이름 에 git 다음에 올 명령을 적는다. git st 가 git status -s 로 실행된다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev; git config user.email dev@example.com; git config core.editor true\\nc() { GIT_AUTHOR_DATE=\\"2026-01-0$2T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$2T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''v1'' > notes.txt; git add -A; c ''add notes'' 1\\necho ''changed'' > notes.txt; echo x > new.txt"]', '["sh", "-c", "( [ \\"$(git -C /tmp/lab/proj config --local --get alias.st)\\" = \\"status -s\\" ] ) && ( [ -s /tmp/q5.txt ] && [ \\"$(cat /tmp/q5.txt)\\" = \\"$(git -C /tmp/lab/proj status -s)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "별칭 st 가 status -s 로 설정돼 있다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj config --local --get alias.st)\\" = \\"status -s\\" ]"]}, {"label": "q5.txt 가 지금의 git status -s 출력과 같다", "cmd": ["sh", "-c", "[ -s /tmp/q5.txt ] && [ \\"$(cat /tmp/q5.txt)\\" = \\"$(git -C /tmp/lab/proj status -s)\\" ]"]}]', '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 373 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 6, '옛 버전의 파일만 되살리기 (git restore --source)', '`/tmp/lab/proj` 의 `config.txt` 는 커밋 3개에 걸쳐 `mode=a` → `mode=b` → `mode=c` 로 바뀌었습니다. **`HEAD` 에서 두 커밋 전** 의 `config.txt` 로 **작업 폴더의 파일만** 되돌리세요. 새 커밋을 만들거나 `HEAD` 를 옮기지 마세요(변경은 커밋하지 않은 상태로 남깁니다).', '`git restore --source=커밋 파일` 은 그 커밋 시점의 파일 내용으로 작업 폴더의 파일을 바꿉니다. `HEAD~2` 는 `HEAD` 에서 두 커밋 전입니다.', 'cd /tmp/lab/proj
git restore --source=HEAD~2 config.txt
cat config.txt
git status --short

# restore --source 는 지정한 커밋 시점의 파일 내용을 작업 폴더에 되살린다. HEAD 는 움직이지 않는다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev; git config user.email dev@example.com; git config core.editor true\\nc() { GIT_AUTHOR_DATE=\\"2026-01-0$2T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$2T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''mode=a'' > config.txt; git add -A; c ''config a'' 1\\necho ''mode=b'' > config.txt; git add -A; c ''config b'' 2\\necho ''mode=c'' > config.txt; git add -A; c ''config c'' 3"]', '["sh", "-c", "( [ \\"$(cat /tmp/lab/proj/config.txt)\\" = \\"mode=a\\" ] ) && ( [ \\"$(git -C /tmp/lab/proj rev-list --count HEAD)\\" = 3 ] && [ \\"$(git -C /tmp/lab/proj log -1 --format=%s)\\" = \\"config c\\" ] ) && ( [ \\"$(git -C /tmp/lab/proj status --short)\\" = \\" M config.txt\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "config.txt 가 mode=a 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/lab/proj/config.txt)\\" = \\"mode=a\\" ]"]}, {"label": "커밋은 그대로 3개다 (최신은 config c)", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj rev-list --count HEAD)\\" = 3 ] && [ \\"$(git -C /tmp/lab/proj log -1 --format=%s)\\" = \\"config c\\" ]"]}, {"label": "커밋하지 않은 변경으로 남아 있다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj status --short)\\" = \\" M config.txt\\" ]"]}]', '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 373 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 7, '충돌 난 rebase 풀고 이어가기', '**배경** — rebase 중에도 같은 줄을 서로 다르게 고쳤으면 **충돌** 이 납니다. 충돌 표시를 고치고 `git add` 한 뒤 `git rebase --continue` 로 이어가면 됩니다(이 연습 환경은 커밋 메시지 편집기를 자동으로 넘기도록 설정돼 있습니다).

**문제** — `feature` 는 `settings.txt` 의 `retries` 를 **5** 로, `main` 은 **3** 으로 고쳤습니다. 지금 `feature` 에 있습니다. `feature` 를 `main` 위로 **rebase** 하되, 충돌은 **`feature` 의 값(`retries=5`)을 살려** 풀고 rebase 를 끝내세요. 최종 `settings.txt` 는 `timeout=10`, `retries=5` 두 줄이어야 합니다.', '`git rebase main` 에서 충돌이 나면 `settings.txt` 를 편집해 표시(`<<<<<<<` 등)를 지우고 원하는 줄만 남긴 뒤, `git add settings.txt` → `git rebase --continue` 입니다.', 'cd /tmp/lab/proj
git rebase main
printf ''timeout=10\\nretries=5\\n'' > settings.txt
git add settings.txt
git rebase --continue
cat settings.txt
git log --oneline --graph

# 충돌 파일을 고쳐 add 한 뒤 rebase --continue 로 마무리한다. 값은 feature 쪽(retries=5)을 살린다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev; git config user.email dev@example.com; git config core.editor true\\nc() { GIT_AUTHOR_DATE=\\"2026-01-0$2T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$2T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\nprintf ''timeout=10\\\\nretries=1\\\\n'' > settings.txt; git add -A; c ''add settings'' 1\\ngit switch -q -c feature\\nprintf ''timeout=10\\\\nretries=5\\\\n'' > settings.txt; git add -A; c ''raise retries to 5'' 2\\ngit switch -q main\\nprintf ''timeout=10\\\\nretries=3\\\\n'' > settings.txt; git add -A; c ''raise retries to 3'' 3\\ngit switch -q feature"]', '["sh", "-c", "( [ ! -d /tmp/lab/proj/.git/rebase-merge ] && [ ! -d /tmp/lab/proj/.git/rebase-apply ] && [ \\"$(git -C /tmp/lab/proj rev-parse --abbrev-ref HEAD)\\" = feature ] ) && ( [ \\"$(cat /tmp/lab/proj/settings.txt)\\" = \\"$(printf \\"timeout=10\\\\nretries=5\\")\\" ] ) && ( [ \\"$(git -C /tmp/lab/proj merge-base main feature)\\" = \\"$(git -C /tmp/lab/proj rev-parse main)\\" ] && [ \\"$(git -C /tmp/lab/proj rev-list --count main..feature)\\" = 1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "rebase 가 끝났다 (진행 중이 아니다)", "cmd": ["sh", "-c", "[ ! -d /tmp/lab/proj/.git/rebase-merge ] && [ ! -d /tmp/lab/proj/.git/rebase-apply ] && [ \\"$(git -C /tmp/lab/proj rev-parse --abbrev-ref HEAD)\\" = feature ]"]}, {"label": "settings.txt 가 timeout=10, retries=5 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/lab/proj/settings.txt)\\" = \\"$(printf \\"timeout=10\\\\nretries=5\\")\\" ]"]}, {"label": "feature 가 main 위에 한 줄로 쌓였다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj merge-base main feature)\\" = \\"$(git -C /tmp/lab/proj rev-parse main)\\" ] && [ \\"$(git -C /tmp/lab/proj rev-list --count main..feature)\\" = 1 ]"]}]', '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 373 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 8, '충돌 난 병합 취소하기 (git merge --abort)', '`main` 과 `feature` 가 `settings.txt` 의 같은 줄을 서로 다르게 고쳤습니다. 지금 `main` 에 있습니다. `feature` 를 **병합해 보고**(충돌이 납니다), 충돌 상태의 **`git status --short`** 출력을 **`/tmp/q8.txt`** 에 저장한 뒤, **병합을 취소** 해서 병합 전 상태로 되돌리세요.', '병합이 충돌로 멈춘 상태에서 `git merge --abort` 를 하면 병합을 시작하기 전 상태로 되돌아갑니다. 충돌 중인 파일은 `git status --short` 에 `UU` 로 보입니다.', 'cd /tmp/lab/proj
git merge feature
git status --short > /tmp/q8.txt
git merge --abort
cat /tmp/q8.txt
git status --short

# merge 가 충돌로 멈추면 UU 표시가 나온다. merge --abort 로 병합 전으로 돌아온다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev; git config user.email dev@example.com; git config core.editor true\\nc() { GIT_AUTHOR_DATE=\\"2026-01-0$2T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$2T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\nprintf ''timeout=10\\\\nretries=1\\\\n'' > settings.txt; git add -A; c ''add settings'' 1\\ngit switch -q -c feature\\nprintf ''timeout=10\\\\nretries=5\\\\n'' > settings.txt; git add -A; c ''raise retries to 5'' 2\\ngit switch -q main\\nprintf ''timeout=10\\\\nretries=3\\\\n'' > settings.txt; git add -A; c ''raise retries to 3'' 3"]', '["sh", "-c", "( grep -q \\"^UU settings.txt\\" /tmp/q8.txt ) && ( [ ! -e /tmp/lab/proj/.git/MERGE_HEAD ] ) && ( [ -z \\"$(git -C /tmp/lab/proj status --short)\\" ] ) && ( [ \\"$(git -C /tmp/lab/proj log -1 --format=%s main)\\" = \\"raise retries to 3\\" ] && [ \\"$(git -C /tmp/lab/proj rev-list --count main)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q8.txt 에 충돌 표시(UU settings.txt)가 있다", "cmd": ["sh", "-c", "grep -q \\"^UU settings.txt\\" /tmp/q8.txt"]}, {"label": "병합이 취소됐다 (진행 중이 아니다)", "cmd": ["sh", "-c", "[ ! -e /tmp/lab/proj/.git/MERGE_HEAD ]"]}, {"label": "작업 폴더가 깨끗하다", "cmd": ["sh", "-c", "[ -z \\"$(git -C /tmp/lab/proj status --short)\\" ]"]}, {"label": "main 은 병합 전 그대로다", "cmd": ["sh", "-c", "[ \\"$(git -C /tmp/lab/proj log -1 --format=%s main)\\" = \\"raise retries to 3\\" ] && [ \\"$(git -C /tmp/lab/proj rev-list --count main)\\" = 2 ]"]}]', '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 373 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 9, '문자열이 나타나거나 사라진 커밋 찾기 (git log -S)', '**배경** — `git log -S문자열` 은 그 문자열의 **개수가 바뀐** 커밋(문자열이 **추가되거나 삭제된** 커밋)만 보여 줍니다. "이 설정은 언제 들어왔고 언제 빠졌지?" 를 찾을 때 씁니다.

**문제** — `app.txt` 의 문자열 **`debug=true`** 가 **추가되거나 삭제된 커밋** 의 제목을 **오래된 것부터** 한 줄씩 **`/tmp/q9.txt`** 에 저장하세요. (제목만, 다른 정보 없이)', '`git log -S문자열` 로 거르고, `--format=%s` 로 제목만 뽑고, `--reverse` 로 오래된 것부터 정렬합니다.', 'cd /tmp/lab/proj
git log -S''debug=true'' --format=%s --reverse > /tmp/q9.txt
cat /tmp/q9.txt

# -S 는 문자열 개수가 바뀐 커밋만 보여 준다. 추가한 커밋(enable debug flag)과 삭제한 커밋(remove debug flag)이 나온다', '["sh", "-c", "rm -rf /tmp/lab /tmp/*.txt; mkdir -p /tmp/lab/proj && cd /tmp/lab/proj\\ngit init -q -b main\\ngit config user.name Dev; git config user.email dev@example.com; git config core.editor true\\nc() { GIT_AUTHOR_DATE=\\"2026-01-0$2T10:00:00+0000\\" GIT_COMMITTER_DATE=\\"2026-01-0$2T10:00:00+0000\\" git commit -q -m \\"$1\\"; }\\necho ''name=app'' > app.txt; git add -A; c ''add app'' 1\\necho ''timeout=30'' >> app.txt; git add -A; c ''add timeout'' 2\\necho ''debug=true'' >> app.txt; git add -A; c ''enable debug flag'' 3\\necho ''name=app2'' > app.txt; echo ''timeout=30'' >> app.txt; echo ''debug=true'' >> app.txt; git add -A; c ''rename app'' 4\\necho ''name=app2'' > app.txt; echo ''timeout=30'' >> app.txt; git add -A; c ''remove debug flag'' 5"]', '["sh", "-c", "( [ \\"$(cat /tmp/q9.txt)\\" = \\"$(printf \\"enable debug flag\\\\nremove debug flag\\")\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "q9.txt 가 추가한 커밋과 삭제한 커밋의 제목 두 줄이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/q9.txt)\\" = \\"$(printf \\"enable debug flag\\\\nremove debug flag\\")\\" ]"]}]', '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 373 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 10, '이미 공유한 브랜치를 rebase 하면?', '동료와 함께 쓰는(이미 push 한) 브랜치의 커밋들을 `git rebase` 로 옮기면 **어떤 문제** 가 생길까요?', '`rebase` 가 옮긴 커밋을 어떻게 만드는지 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["모든 커밋의 내용이 자동으로 삭제된다", "커밋이 새 해시로 다시 만들어져 동료의 이력과 갈라지고 충돌이 생기기 쉽다", "원격 저장소가 브랜치를 자동으로 삭제한다", "병합 커밋이 항상 두 개씩 생긴다"]', 1, '`rebase` 는 커밋을 옮기는 것이 아니라 **같은 내용으로 새 커밋(새 해시)을 만드는 것**입니다. 이미 공유한 커밋을 이렇게 바꾸면 동료가 가진 옛 커밋과 이력이 갈라져 혼란과 충돌이 생기므로, 공유 전의 내 브랜치에만 쓰는 것이 원칙입니다.', NULL, NULL, NULL, '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 373 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 11, 'bisect 자동으로 돌리기', '좋은 커밋과 나쁜 커밋을 정한 뒤, 검사 스크립트로 처음 나쁜 커밋을 **자동으로** 찾는 명령입니다. 빈칸을 채우세요.', '"실행한다"는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["run", "auto", "test", "exec"]', NULL, '`git bisect run 명령` 은 중간 커밋마다 명령을 실행해 종료 코드(0 이면 좋음, 아니면 나쁨)로 자동 판정하며 처음 나쁜 커밋을 찾습니다. `auto`·`test`·`exec` 는 `bisect` 의 하위 명령이 아닙니다.', '[0]', 'git bisect {0} sh /tmp/lab/check.sh', NULL, '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 373 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 373, 12, 'git bisect 로 나쁜 커밋 찾는 흐름', '`git bisect` 로 버그가 처음 들어온 커밋을 찾아 정리하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '시작 → 나쁨·좋음 알림 → 반복 → 끝내기 순서예요.', NULL, NULL, '[]', 'order', '["`git bisect start` 로 탐색을 시작한다", "`git bisect bad` 로 지금 커밋이 나쁘다고 알린다", "`git bisect good 커밋` 으로 좋았던 커밋을 알린다", "나오는 중간 커밋을 확인해 `good`/`bad` 를 알리며 범위를 줄인다", "`git bisect reset` 으로 원래 브랜치로 돌아온다"]', NULL, '탐색을 시작하고 나쁜 커밋과 좋은 커밋을 알려 주면, Git 이 중간 커밋을 체크아웃해 줍니다. 그 커밋을 확인해 `good`/`bad` 를 알리며 범위를 반씩 줄이다가 처음 나쁜 커밋이 나오면, `bisect reset` 으로 원래 상태로 돌아옵니다.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "git rebase 문서", "url": "https://git-scm.com/docs/git-rebase"}, {"title": "git merge 문서", "url": "https://git-scm.com/docs/git-merge"}, {"title": "git bisect 문서", "url": "https://git-scm.com/docs/git-bisect"}, {"title": "git clean 문서", "url": "https://git-scm.com/docs/git-clean"}, {"title": "git restore 문서", "url": "https://git-scm.com/docs/git-restore"}, {"title": "git log 문서", "url": "https://git-scm.com/docs/git-log"}, {"title": "git config 문서", "url": "https://git-scm.com/docs/git-config"}]'
